import{_ as a,o as t,c as o,ae as s}from"./chunks/framework.EHGTsUvI.js";const c=JSON.parse('{"title":"Log Storage","description":"","frontmatter":{"title":"Log Storage"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/logstorage.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/logstorage.md"}'),r={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/logstorage.md"};function n(i,e,l,g,p,d){return t(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="log-storage" tabindex="-1">Log Storage <a class="header-anchor" href="#log-storage" aria-label="Permalink to &quot;Log Storage&quot;">​</a></h1><p>Log Storage is a storage building used to store harvested <strong>Logs</strong>. It allows players to store large quantities of logs without needing to keep them inside trailers or other vehicles.</p><p>Log Storage is particularly useful for large-scale logging and production chains where logs need to be stored before being transported to <strong>LumberCo</strong> or other locations.</p><h2 id="building-information" tabindex="-1">Building Information <a class="header-anchor" href="#building-information" aria-label="Permalink to &quot;Building Information&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Building</td><td>Log Storage</td></tr><tr><td>Purpose</td><td>Log Storage</td></tr><tr><td>Capacity</td><td>Infinite</td></tr><tr><td>Storage Type</td><td>Logs</td></tr><tr><td>Required Liscense</td><td><strong>To be confirmed</strong></td></tr></tbody></table><h2 id="stored-logs" tabindex="-1">Stored Logs <a class="header-anchor" href="#stored-logs" aria-label="Permalink to &quot;Stored Logs&quot;">​</a></h2><p>Log Storage can be used to store harvested logs.</p><p>The storage is designed specifically for logs rather than crops, liquids, or finished factory products.</p><h2 id="how-to-use-log-storage" tabindex="-1">How to Use Log Storage <a class="header-anchor" href="#how-to-use-log-storage" aria-label="Permalink to &quot;How to Use Log Storage&quot;">​</a></h2><h3 id="_1-purchase-the-storage" tabindex="-1">1. Purchase the Storage <a class="header-anchor" href="#_1-purchase-the-storage" aria-label="Permalink to &quot;1. Purchase the Storage&quot;">​</a></h3><p>Open the <strong>Create</strong> menu and purchase the Log Storage.</p><p>Place the storage somewhere accessible to your logging equipment and transport vehicles.</p><h3 id="_2-load-logs" tabindex="-1">2. Load Logs <a class="header-anchor" href="#_2-load-logs" aria-label="Permalink to &quot;2. Load Logs&quot;">​</a></h3><p>Bring harvested logs to the Log Storage using a suitable vehicle or trailer.</p><p>Unload the logs into the storage area.</p><p>The logs will be added to the storage.</p><h3 id="_3-store-logs" tabindex="-1">3. Store Logs <a class="header-anchor" href="#_3-store-logs" aria-label="Permalink to &quot;3. Store Logs&quot;">​</a></h3><p>Once the logs have been deposited, they remain stored inside the Log Storage until they are needed.</p><p>The storage capacity is currently <strong>to be confirmed</strong>.</p><h3 id="_4-remove-logs" tabindex="-1">4. Remove Logs <a class="header-anchor" href="#_4-remove-logs" aria-label="Permalink to &quot;4. Remove Logs&quot;">​</a></h3><p>When you need the stored logs for transportation or production, use a suitable vehicle or trailer at the storage&#39;s loading area.</p><p>The stored logs can then be transferred onto the vehicle for transportation.</p><h2 id="log-storage-chain" tabindex="-1">Log Storage Chain <a class="header-anchor" href="#log-storage-chain" aria-label="Permalink to &quot;Log Storage Chain&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Forest</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Cut Trees</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Harvested Logs</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Log Storage</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>┌───────────────┐</span></span>
<span class="line"><span>│               │</span></span>
<span class="line"><span>LumberCo      Other</span></span>
<span class="line"><span>│             Uses</span></span>
<span class="line"><span>Production</span></span></code></pre></div><h2 id="uses" tabindex="-1">Uses <a class="header-anchor" href="#uses" aria-label="Permalink to &quot;Uses&quot;">​</a></h2><p>Log Storage is especially useful for:</p><ul><li>Storing logs between harvesting trips</li><li>Building up large quantities of logs</li><li>Supplying <strong>LumberCo</strong></li><li>Reducing the need for multiple trailers</li><li>Preparing logs for production</li><li>Keeping harvested logs organised on your farm</li></ul><blockquote><p><strong>Tip:</strong> Log Storage is particularly useful for players who regularly harvest large quantities of logs for <strong>LumberCo</strong>, allowing materials to be stockpiled before transporting them.</p></blockquote><blockquote><p><strong>Note:</strong> Storage prices, capacities, and functionality may change with future game updates.</p></blockquote>`,29)])])}const u=a(r,[["render",n]]);export{c as __pageData,u as default};
